'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { normalizarNomeInsumo } from '@/lib/estoque-nome';
import type { StockCategory, StockItem } from '../types';
import type { EstoqueConfigMap } from './useEstoqueConfig';

export interface ProdutoEstoque {
  id: string;        // DB id (cuid)
  insumoId: string;  // slug identificador
  nome: string;
  unidade: string;
  sessaoId: string;
  sessaoNome: string;
  sessaoIcone: string;
}

interface EstoqueInsumoDb {
  id: string;
  insumoId: string;
  nome: string;
  unidade: string;
  categoriaId: string;
  categoriaNome: string;
  categoriaIcone: string;
}

async function fetchInsumos(): Promise<EstoqueInsumoDb[]> {
  const res = await fetch('/api/estoque/insumos', { cache: 'no-store' });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

function mapInsumos(data: EstoqueInsumoDb[]): ProdutoEstoque[] {
  return data.map(p => ({
    id: p.id,
    insumoId: p.insumoId,
    nome: p.nome,
    unidade: p.unidade,
    sessaoId: p.categoriaId,
    sessaoNome: p.categoriaNome,
    sessaoIcone: p.categoriaIcone,
  }));
}

// Constrói sessões de contagem a partir dos insumos vindos do banco,
// aplicando config do usuário (ativo, estoqueMinimo, modo, kg/un).
export function construirSessoes(
  insumos: ProdutoEstoque[],
  config: EstoqueConfigMap = {},
  productOrder: string[] = [],
): StockCategory[] {
  // Um produto por nome (catálogo compartilhado — evita triplicar por loja)
  const porNome = new Map<string, ProdutoEstoque>();
  for (const p of insumos) {
    const key = normalizarNomeInsumo(p.nome);
    if (!porNome.has(key)) porNome.set(key, p);
  }
  const unicos = Array.from(porNome.values());

  // Agrupa por categoria
  const categorias = new Map<string, { nome: string; icone: string; itens: ProdutoEstoque[] }>();
  for (const p of unicos) {
    if (!categorias.has(p.sessaoId)) {
      categorias.set(p.sessaoId, { nome: p.sessaoNome, icone: p.sessaoIcone, itens: [] });
    }
    categorias.get(p.sessaoId)!.itens.push(p);
  }

  return Array.from(categorias.entries())
    .map(([categoriaId, cat]) => {
      const itens: StockItem[] = cat.itens
        .filter(p => {
          const cfg = config[p.insumoId];
          return cfg === undefined || cfg.ativo !== false;
        })
        .map(p => {
          const cfg = config[p.insumoId];
          return {
            insumoId: p.insumoId,
            nome: p.nome,
            unidade: p.unidade,
            quantidadeContada: null,
            estoqueMinimo: cfg?.estoqueMinimo,
            modoContagem: cfg?.modoContagem ?? (p.unidade === 'un' ? 'unidade' : 'kg'),
            kgPorUnidade: cfg?.kgPorUnidade,
            observacao: undefined,
          };
        })
        .sort((a, b) => {
          if (productOrder.length === 0) return 0;
          const ia = productOrder.indexOf(a.insumoId);
          const ib = productOrder.indexOf(b.insumoId);
          if (ia === -1 && ib === -1) return 0;
          if (ia === -1) return 1;
          if (ib === -1) return -1;
          return ia - ib;
        });

      return {
        id: categoriaId,
        nome: cat.nome,
        icone: cat.icone,
        status: 'pendente' as const,
        itens,
      };
    })
    .filter(s => s.itens.length > 0);
}

export function useProdutosEstoque(
  config: EstoqueConfigMap = {},
  productOrder: string[] = [],
) {
  const [insumos, setInsumos] = useState<ProdutoEstoque[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const requestIdRef = useRef(0);

  const load = useCallback(async (): Promise<ProdutoEstoque[] | undefined> => {
    const reqId = ++requestIdRef.current;
    setIsLoading(true);
    setError(null);
    try {
      const data = await fetchInsumos();
      const mapped = mapInsumos(data);
      // Ignora respostas antigas (evita sobrescrever lista após deletes sequenciais)
      if (reqId !== requestIdRef.current) return mapped;
      setInsumos(mapped);
      return mapped;
    } catch (err) {
      if (reqId !== requestIdRef.current) return undefined;
      console.error('[useProdutosEstoque]', err);
      setError('Não foi possível carregar os produtos.');
      return undefined;
    } finally {
      if (reqId === requestIdRef.current) setIsLoading(false);
    }
  }, []);

  /** Remove da lista local por cuid e/ou slug (evita o item "voltar" no merge). */
  const removeLocal = useCallback((id: string, insumoId?: string) => {
    setInsumos(prev =>
      prev.filter(p => p.id !== id && (!insumoId || p.insumoId !== insumoId)),
    );
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const sessoes = construirSessoes(insumos, config, productOrder);

  return {
    produtos: insumos,
    sessoes,
    isLoading,
    error,
    refetch: load,
    removeLocal,
  };
}
